-- gen623: 20 zone cambiate, 41 tessere
-- 5319ff40121d588ae12991f6178128e2 (1052950) → 3867679ff319995d9024e18abc4b2425 (1063404)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '3867679ff319995d9024e18abc4b2425' as combacia
from kv_store where key like 'tmp:gen623:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen623:p%')
where key='app:jsx:src'
  and md5(value) = '5319ff40121d588ae12991f6178128e2'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen623:p%') = '3867679ff319995d9024e18abc4b2425';

update kv_store set value = '{"len":1063404,"ver":"gen-6.23"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '3867679ff319995d9024e18abc4b2425';

delete from kv_store where key like 'tmp:gen623:p%';
